<div class="modal fade" id="detail_target_kpi" tabindex="-1" role="dialog">    <div class="modal-dialog">		<?php echo form_open(admin_url('target_kpi/detail/' . $id.'/' . $year.'/' . $month), array('id' => 'form_target_kpi')); ?>        <div class="modal-content">            <div class="modal-header">                <button type="button" class="close" data-dismiss="modal" aria-label="Close">                    <span aria-hidden="true">&times;</span>                </button>                <h4 class="modal-title">                    <span class="edit-title"><?= !empty($title) ? $title : '' ?></span>                </h4>            </div>            <div class="modal-body">                <div class="row">                    <div class="col-md-12">                        <input type="hidden" name="save" value="1">                        <table class="table_tagert table table-hover dont-responsive-table dataTable">                            <thead>                                <tr>                                    <th style="width: 50px;text-align: center"><a onclick="addItem()"><i class="fa fa-plus"></i></a></th>                                    <th>Phòng Ban</th>                                    <th>Số Tiền</th>                                    <th style="width: 50px">Tác vụ</th>                                </tr>                            </thead>                            <tbody>                                <?php $counter = 0;if(!empty($cost_target)){?>                                    <?php foreach ($cost_target as $key => $value){ ?>                                            <?php                                                $optionDepartment = '';                                                if (!empty($dtDepartment)){                                                    foreach ($dtDepartment as $k => $v){                                                        $optionDepartment .= '<option '.($v['departmentid'] == $value['department_id'] ? 'selected' : '').' value="'.$v['departmentid'].'">'.$v['name'].'</option>';                                                    }                                                }                                            ?>                                          <tr>                                              <td class="text-center stt"><?= ++$key ?></td>                                              <td><select id="department_id_<?= $counter ?>" name="department_id[]" class="department_id"><?= $optionDepartment ?></select></td>                                              <td><input type="text" class="money form-control number-format" name="money[]" value="<?= formatMoney($value['money']) ?>">                                                  <input type="hidden" name="counter[]" class="counter" value="<?= $counter ?>">                                                  <input type="hidden" name="id_item[]" class="id_item" value="<?= $value['id'] ?>">                                              </td>                                              <td class="text-center pointer" onclick="removeRow(this)"><i class="fa fa-remove"></i></td>                                          </tr>                                    <?php  $counter++;} ?>                                <?php } ?>                            </tbody>                        </table>                    </div>                </div>            </div>            <div class="modal-footer">                <button type="submit" class="btn btn-info">					<?php echo _l('submit'); ?>                </button>                <button type="button" class="btn btn-danger" data-dismiss="modal">					<?php echo _l('close'); ?>                </button>            </div>        </div>		<?php echo form_close(); ?>    </div></div><script>    var counter = <?= !empty($counter) ? $counter : 0 ?>;    var count_errors = 0;    var dtDepartment = <?= !empty($dtDepartment) ? json_encode($dtDepartment) : '{}' ?>;    $(function () {        // $(".department_id").selectpicker();        $('#detail_target_kpi').modal('show');        appValidateForm($('#form_target_kpi'), {        }, manage_target_kpi);    });    for (i = 0;i <= counter; i++) {        $(`#department_id_${i}`).select2();    }    function addItem(){        tdStt = `<div class="stt"></div>`;        tdType = `<div>            <select class="department_id" id="department_id_${counter}" name="department_id[${counter}]" style="width: 100%;"  data-placeholder="<?= lang('Phòng ban') ?>">                ${optionDepartment()}            </select>        </div>`;        tdName = `<div class="money">         <input type="hidden" name="counter[]" class="counter" value="${counter}">         <input type="text" name="money[${counter}]" required class="money form-control number-format" value="">        </div>`;        tdActions = `<a onclick="removeRow(this)" href="javascript:void(0)" class="fa fa-remove remove-row"></a>`;        trItem = `<tr>            <td class="text-center">${tdStt}</td>            <td>${tdType}</td>            <td>${tdName}</td>            <td class="td-actions text-center">${tdActions}</td>        </tr>`;        $(".table_tagert").find('tbody').append(trItem);        $(`#department_id_${counter}`).select2();        $(`#department_id_${counter}`).attr('required','required');        counter ++;        getTotal();    }    function removeRow(el)    {        $(el).closest('tr').remove();        getTotal();    }    function getTotal(){        tb = '.table_tagert tbody tr:not("[class^=not-tr]")';        count_errors = 0;        var n = $(tb).length;        var stt = 0;        for (ii = 0; ii < n; ii++)        {            stt++;            element = $(tb)[ii];            $(element).find('.stt').html(stt);        }    }    function optionDepartment(selected_id = 0){        option = `<option></option>`;        $.each(dtDepartment, function(index, el) {            selected = selected_id == el.departmentid ? 'selected' : '';            option+= '<option '+selected+' value="'+el.departmentid+'">'+el.name+'</option>';        });        return option;    }        function manage_target_kpi(form) {        var data = $(form).serialize();        var url = form.action;        $.post(url, data).done(function (response) {            response = JSON.parse(response);            if (response.success == true) {                alert_float('success', response.message);                $('#detail_target_kpi').modal('hide');            }            $('.table-target_room').DataTable().ajax.reload();        });        return false;    }</script>